-- Correcciones de S4 sobre las filas que cargó S1 (scripts/migrar-legacy.mjs), ya publicadas. Aplicadas el 2026-10-22
-- con execute_sql, en este orden. Si se vuelve a ejecutar migrar-legacy, hay que aplicar este archivo después.
-- Textos de proyectos: idénticos a plan/contenido (comprobado por hash). Aquí solo lo que difería.

-- Pósteres nuevos: El Padrino (la URL de i9.ytimg.com caducaba) y Reels (la imagen de rbgescuela no era de Josep)
insert into public.medios (url_origen, tipo, titulo, texto_alternativo)
select v.url, 'imagen', v.titulo, v.alt
from (values
  ('https://i.ytimg.com/vi/WnSCN4aXDKA/maxresdefault.jpg', 'recreacion-el-padrino-01', 'Fotograma de Recreación de ''El Padrino'''),
  ('https://i.ytimg.com/vi/rUv-Ql7NxCQ/hqdefault.jpg', 'reels-redes-sociales-01', 'Fotograma de Reels para redes')
) v(url, titulo, alt)
where not exists (select 1 from public.medios m where m.url_origen = v.url);

update public.proyectos set
  imagen_id = (select id from public.medios where url_origen = 'https://i.ytimg.com/vi/WnSCN4aXDKA/maxresdefault.jpg' limit 1),
  galeria = (
    select jsonb_agg(case when m.url_origen like 'https://i9.ytimg.com/%'
      then jsonb_set(g.e, '{medio}', to_jsonb((select id from public.medios where url_origen = 'https://i.ytimg.com/vi/WnSCN4aXDKA/maxresdefault.jpg' limit 1)))
      else g.e end order by g.n)
    from jsonb_array_elements(galeria) with ordinality g(e, n) left join public.medios m on m.id = (g.e ->> 'medio')::uuid)
where idioma = 'es' and slug = 'recreacion-el-padrino';

update public.proyectos set
  imagen_id = (select id from public.medios where url_origen = 'https://i.ytimg.com/vi/rUv-Ql7NxCQ/hqdefault.jpg' limit 1),
  galeria = '[]'::jsonb
where idioma = 'es' and slug = 'reels-redes-sociales';

-- Títulos de las secciones de la ficha (los del prototipo D)
update public.proyectos set titulos_seccion = '{"historia":"El proyecto","como_lo_hicimos":"Decisiones clave","el_reto":"El reto","el_resultado":"Resultado"}'::jsonb
where idioma = 'es';

-- Cámara de las recreaciones con el mismo formato que el resto de fichas
update public.proyectos set camara = 'Sony FX3 · Tamron y Sony'
where idioma = 'es' and camara = 'Sony FX3 · ópticas Tamron y Sony';

-- Artículos: título y extracto de datos.ts, portada y fotos del cuerpo (enlazadas a medios)
with d as (select $datos$[{"slug":"el-arte-de-contar-historias-con-luz","id_antiguo":"el-arte-de-contar-historias-con-luz","titulo":"Dirección de fotografía: el arte de contar historias con luz","fecha":"2024-07-15","extracto":"La luz es el pincel del director de fotografía. Cómo un esquema de luz cambia lo que sentimos.","categoria":"Dirección de fotografía","imagen":"https://www.platinocrowdfunding.com/storage/project/5454/img/eO2uv54rRAQy1AgsNjm0ybjXLN92jg4mkW9zFxZR.png","contenido":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Cuando empiezo un proyecto, lo primero que me pregunto no es qué cámara voy a usar. Me pregunto qué quiero que sienta quien mira. La luz es la forma más directa que tengo de decidirlo: un cambio pequeño en su dirección o en su calidad puede convertir un espacio acogedor en uno amenazante, o a un personaje en alguien en quien confiar o de quien desconfiar."}]},{"type":"paragraph","content":[{"type":"text","text":"Me obsesiona la luz natural. Me fijo en cómo cae a distintas horas, en la suavidad de la hora mágica, en cómo se cuela por una persiana. Pero no siempre se puede depender de ella, y ahí empieza el oficio: recrearla, o inventar otra, con difusores, reflectores y una posición muy cuidada."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Cuando la luz sale de la mente"}]},{"type":"paragraph","content":[{"type":"text","text":"En "},{"type":"text","text":"El Cirujano","marks":[{"type":"italic"}]},{"type":"text","text":" quise que la luz no tuviera una fuente lógica. En las escenas del asesino no hay lámparas ni ventanas que lo justifiquen: la luz sale de su cabeza, y por eso es un rojo abrasador. Todo lo demás, la investigación, es frío y analítico. Ese choque es la historia."}]},{"type":"image","attrs":{"medio":"https://www.platinocrowdfunding.com/storage/project/5454/img/bj9n3eW3a65uyo5krgOrW1dhpgJAtqk8bvY5x687.png","alt":"Escena de El Cirujano con la luz roja del asesino","pie":"El Cirujano. Premio a la mejor fotografía en On Duty International Film Festival."}},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Cuando el color cuenta el tiempo"}]},{"type":"paragraph","content":[{"type":"text","text":"En el EP "},{"type":"text","text":"Oscuridad","marks":[{"type":"italic"}]},{"type":"text","text":" usé el color como reloj. Empezamos la primera canción a todo color y, tema a tema, fuimos desaturando la imagen hasta acabar en blanco y negro. Nadie dice que la relación se está rompiendo; se ve."}]},{"type":"image","attrs":{"medio":"https://i.imgur.com/MgsvdAf.png","alt":"Fotograma del EP Oscuridad de Adrián Muñoz","pie":"EP Oscuridad, Adrián Muñoz."}},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Cuando la luz protege"}]},{"type":"paragraph","content":[{"type":"text","text":"En "},{"type":"text","text":"No se está tan mal","marks":[{"type":"italic"}]},{"type":"text","text":" la luz tenía que ser un refugio. En lugar de iluminar plano, esculpí el espacio con destellos, contraluces y reflejos en cristal y agua, para que el artista estuviera dentro de una burbuja donde pudiera mostrarse sin miedo."}]},{"type":"image","attrs":{"medio":"https://i.ibb.co/tPwcqPyC/No-Se-Esta-Tan-Mal-LOVVA-V4-4k-mp4-snapshot-00-44-400.jpg","alt":"Fotograma de No se está tan mal, de Lovva, con reflejos y contraluces","pie":"No se está tan mal, Lovva."}},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Cuando no tienes nada"}]},{"type":"paragraph","content":[{"type":"text","text":"En mis recreaciones aprendí lo que más me gusta del oficio. Para la ventana de Vito Corleone usé la rejilla de una estufa de butano, cinta negra y papel de horno. Con eso y una luz bien colocada, un sótano se convierte en un despacho de "},{"type":"text","text":"El Padrino","marks":[{"type":"italic"}]},{"type":"text","text":". La luz no necesita presupuesto; necesita intención."}]},{"type":"image","attrs":{"medio":"https://i.ibb.co/jP2769Q5/Captura-de-pantalla-2026-05-13-154204.png","alt":"Recreación del despacho de Vito Corleone de El Padrino","pie":"Recreación de El Padrino, rodada en un sótano."}},{"type":"paragraph","content":[{"type":"text","text":"Cada proyecto es un lienzo distinto, y la luz es siempre mi herramienta principal para contar la historia."}]}]}},{"slug":"ia-artesano-audiovisual","id_antiguo":"ia-artesano-audiovisual","titulo":"El artesano y la inteligencia artificial en el cine","fecha":"2025-05-13","extracto":"Qué cambia la IA en la producción audiovisual y por qué el trabajo artesano sigue importando.","categoria":"Oficio","imagen":"https://i.ibb.co/KxmsqgfX/Captura-de-pantalla-2026-05-13-154839.png","contenido":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"El mundo audiovisual ha sido, hasta ahora, un trabajo artesano. Pero ¿dónde queda nuestra huella cuando una IA puede imitar en segundos un estilo que tardamos años en construir?"}]},{"type":"paragraph","content":[{"type":"text","text":"Esa es la gran duda. En nuestro oficio, la mano, el gusto y la experiencia van puliendo una voz propia. Y aunque una inteligencia artificial pueda replicar una estética, difícilmente tendrá esa \"alma\" o esa riqueza de matices que surgen de la vivencia humana."}]},{"type":"paragraph","content":[{"type":"text","text":"Esta semana he estado dándole muchas vueltas y creo que merece la pena pararse a pensarlo."}]},{"type":"paragraph","content":[{"type":"text","text":"A muchos compañeros, e incluso a mí mismo, nos genera cierto rechazo ver obras generadas al 100 % por IA. A menudo se sienten vacías y, de alguna manera, invasoras. Sin embargo, creo que ese rechazo viene de mirar desde el ángulo equivocado, y de dejar de lado su verdadero potencial."}]},{"type":"paragraph","content":[{"type":"text","text":"La clave está en no ver a la IA como la \"creadora\". Hay que verla como el mejor asistente posible."}]},{"type":"image","attrs":{"medio":"https://i.imgur.com/wij6Im5.jpeg","alt":"Maqueta en miniatura de la Ciudad Nube para la recreación de El Imperio Contraataca","pie":"Una maqueta, siluetas y sables añadidos fotograma a fotograma: mi recreación de El Imperio Contraataca."}},{"type":"paragraph","content":[{"type":"text","text":"Es una herramienta poderosísima para ejecutar ideas que antes eran imposibles sin presupuestos desorbitados. Y la clave está en integrarla en el flujo de trabajo para potenciarnos a nosotros, no para sustituirnos."}]},{"type":"paragraph","content":[{"type":"text","text":"Estamos viendo pasos gigantes en el buen camino. Me gusta mucho el enfoque de Runway: herramientas que buscan darnos control total sobre lo que hacemos, en lugar de dejarlo todo al azar. Su potencial, para mí, está en poder modificar el propio material que hemos grabado: incluir público en un estadio, añadir efectos visuales muy costosos o matizar la iluminación si en rodaje no ha quedado como esperábamos. Lo mismo con lo que se pudo ver la semana pasada en Adobe Max: la integración de la IA generativa directamente en nuestros timelines."}]},{"type":"paragraph","content":[{"type":"text","text":"En conclusión, creo que la tecnología cambia y avanza, pero somos nosotros quienes tenemos que construir el camino, haciendo un uso responsable e inteligente de ella. La inteligencia artificial no va a reemplazar al artesano, pero el artesano que sepa usar estas nuevas herramientas tendrá un taller mucho más potente para materializar su visión."}]}]}}]$datos$::jsonb as j)
update public.articulos t set titulo = a ->> 'titulo', extracto = a ->> 'extracto',
  contenido = jsonb_build_object('type', 'doc', 'content', (
    select jsonb_agg(case when n ->> 'type' = 'image' then jsonb_set(n, '{attrs,medio}', to_jsonb(
      (select id from public.medios where url_origen = n -> 'attrs' ->> 'medio' order by creado_en limit 1))) else n end order by i)
    from jsonb_array_elements(a -> 'contenido' -> 'content') with ordinality e(n, i))),
  imagen_id = (select id from public.medios where url_origen = a ->> 'imagen' order by creado_en limit 1)
from d, jsonb_array_elements(d.j) a
where t.idioma = 'es' and t.slug = a ->> 'slug';
